UPDATE pt_product
SET sold_count = GREATEST(IFNULL(sold_count, 0) - 1, 0)
WHERE id = #{productId}

UPDATE mk_group_buy_activity
SET sold_count = GREATEST(IFNULL(sold_count, 0) - 1, 0)
WHERE id = #{activityId}

UPDATE mk_flash_sale_activity
SET sold_count = GREATEST(IFNULL(sold_count, 0) - 1, 0)
